update r_battle_royale3_record

	profit = case order_no

		when #{item.orderNo} then #{item.profit}

	else profit end,
	lottery_result = case order_no

		when #{item.orderNo} then #{item.lotteryResult}

	else lottery_result end,
	win_or_lose = case order_no

		when #{item.orderNo} then #{item.isWin}

	else win_or_lose end,
	bet_info = case order_no

		when #{item.orderNo} then #{item.betInfo}

	else bet_info end,
	bet_amount = case order_no

		when #{item.orderNo} then #{item.betAmount}

	else bet_amount end,
	status = 1,
	update_time = now()

where order_no in

	#{item.orderNo}
